const items = $input.all();
if (items.length !== 1) throw new Error('Webhook deve receber exatamente um item.');
const input = items[0].json || {};
const headers = input.headers || {};
const ts = String(headers['x-rpb-timestamp'] || '');
const suppliedSignature = String(headers['x-rpb-signature'] || '').replace(/^sha256=/i, '').toLowerCase();
let rawBody = null;
const raw = input.rawBody;
if (typeof raw === 'string') rawBody = raw;
else if (typeof Buffer !== 'undefined' && Buffer.isBuffer(raw)) rawBody = raw.toString('utf8');
else if (raw && raw.type === 'Buffer' && Array.isArray(raw.data) && typeof Buffer !== 'undefined') rawBody = Buffer.from(raw.data).toString('utf8');
if (!rawBody && items[0].binary?.data?.data && typeof Buffer !== 'undefined') {
  rawBody = Buffer.from(items[0].binary.data.data, 'base64').toString('utf8');
}
if (!rawBody) throw new Error('Bloqueado: corpo HTTP bruto ausente. Confira rawBody/binary.data no Webhook; não assine JSON.stringify(body).');
if (!ts || !/^\d{10}$/.test(ts)) throw new Error('Bloqueado: x-rpb-timestamp deve ser Unix time em segundos.');
if (!/^[a-f0-9]{64}$/.test(suppliedSignature)) throw new Error('Bloqueado: x-rpb-signature ausente ou formato inválido.');
const nowSeconds = Math.floor(Date.now() / 1000);
if (Math.abs(nowSeconds - Number(ts)) > 300) throw new Error('Bloqueado: timestamp expirado; tolerância máxima de 300 segundos.');
let body;
try { body = JSON.parse(rawBody); } catch { throw new Error('Bloqueado: o corpo bruto não é JSON válido.'); }
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Bloqueado: o corpo deve ser um objeto JSON.');
const accountId = String(body.accountId || '').trim();
const eventId = String(body.eventId || '').trim();
const action = String(body.action || '').trim();
if (!accountId || accountId.length > 100) throw new Error('Bloqueado: accountId ausente ou inválido.');
if (!eventId || eventId.length > 160) throw new Error('Bloqueado: eventId ausente ou inválido.');
if (!['ingest','pull','result','lead','sale','connection','connections','ping'].includes(action)) throw new Error('Bloqueado: action não permitida.');
let master;
try { master = typeof $env !== 'undefined' ? $env.N8N_WEBHOOK_SECRET : undefined; } catch { master = undefined; }
if (typeof master !== 'string' || master.length === 0) throw new Error('Bloqueado: N8N_WEBHOOK_SECRET não está acessível ao Code node. Confirme N8N_BLOCK_ENV_ACCESS_IN_NODE=false e reinicie o n8n.');
let crypto;
try { crypto = require('crypto'); } catch { throw new Error('Bloqueado: módulo crypto indisponível no Code node. Configure NODE_FUNCTION_ALLOW_BUILTIN=crypto e reinicie o n8n.'); }
const accountSecret = crypto.createHmac('sha256', master).update(accountId).digest('hex');
const expected = crypto.createHmac('sha256', accountSecret).update(ts + '.' + rawBody).digest('hex');
const a = Buffer.from(expected, 'hex');
const b = Buffer.from(suppliedSignature, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Bloqueado: assinatura HMAC inválida.');
return [{ json: { rawBody, timestamp: ts, signature: 'sha256=' + expected, eventId, action, accountId, authenticated: true } }];
